import AppKit
import ImageIO
import UniformTypeIdentifiers

func buckets(_ bytes:[UInt8])->[(Int,Int)]{var count:[Int:Int]=[:];for i in stride(from:0,to:bytes.count-3,by:4){if bytes[i+3]<128{continue};let key=Int(bytes[i]>>4)<<8|Int(bytes[i+1]>>4)<<4|Int(bytes[i+2]>>4);count[key,default:0]+=1};return count.sorted{$0.value==$1.value ? $0.key<$1.key:$0.value>$1.value}.map{($0.key,$0.value)}}
func palette(_ url:URL)throws->[(Int,Int)]{guard let src=CGImageSourceCreateWithURL(url as CFURL,nil),let image=CGImageSourceCreateThumbnailAtIndex(src,0,[kCGImageSourceCreateThumbnailFromImageAlways:true,kCGImageSourceThumbnailMaxPixelSize:64]as CFDictionary)else{throw NSError(domain:"Unreadable image",code:1)};let w=image.width,h=image.height;var bytes=[UInt8](repeating:0,count:w*h*4);let ok=bytes.withUnsafeMutableBytes{raw->Bool in guard let ctx=CGContext(data:raw.baseAddress,width:w,height:h,bitsPerComponent:8,bytesPerRow:w*4,space:CGColorSpaceCreateDeviceRGB(),bitmapInfo:CGImageAlphaInfo.premultipliedLast.rawValue|CGBitmapInfo.byteOrder32Big.rawValue)else{return false};ctx.draw(image,in:CGRect(x:0,y:0,width:w,height:h));return true};if !ok{throw NSError(domain:"Cannot rasterize",code:2)};return buckets(bytes)}

@MainActor final class Delegate:NSObject,NSApplicationDelegate{
 var window:NSWindow!;let output=NSTextView();let setting=NSTextField(string:"8")
 func applicationDidFinishLaunching(_ notification:Notification){NSApp.setActivationPolicy(.regular);window=NSWindow(contentRect:NSRect(x:0,y:0,width:900,height:650),styleMask:[.titled,.closable,.resizable],backing:.buffered,defer:false);window.title="Image Palette Studio";window.isReleasedWhenClosed=false;let root=window.contentView!;let label=NSTextField(labelWithString:"Top 1–16 quantized RGB colors from an image thumbnail.");label.frame=NSRect(x:20,y:590,width:850,height:30);root.addSubview(label);setting.frame=NSRect(x:20,y:545,width:520,height:30);root.addSubview(setting);let button=NSButton(title:"Choose image",target:self,action:#selector(run));button.frame=NSRect(x:560,y:545,width:280,height:30);root.addSubview(button);let scroll=NSScrollView(frame:NSRect(x:20,y:20,width:850,height:500));scroll.autoresizingMask=[.width,.height];scroll.hasVerticalScroller=true;output.isEditable=false;output.font = .monospacedSystemFont(ofSize:14,weight:.regular);output.isVerticallyResizable=true;output.autoresizingMask=[.width];output.textContainer?.widthTracksTextView=true;scroll.documentView=output;root.addSubview(scroll);window.center();window.makeKeyAndOrderFront(nil);NSApp.activate(ignoringOtherApps:true)}
 @objc func run(){do{
guard let count=Int(setting.stringValue),count>=1,count<=16 else{throw NSError(domain:"Count 1–16",code:1)};let panel=NSOpenPanel();panel.allowedContentTypes=[.image];guard panel.runModal() == .OK,let url=panel.url else{return};let values=try palette(url);output.string=values.prefix(count).map{key,n in let r=((key>>8)&15)*17,g=((key>>4)&15)*17,b=(key&15)*17;return String(format:"#%02X%02X%02X · %d thumbnail pixels",r,g,b,n)}.joined(separator:"\n")
}catch{output.string="Error: \(error.localizedDescription)"}}
 func applicationShouldTerminateAfterLastWindowClosed(_ sender:NSApplication)->Bool{true}
}
@main struct LocalApp{@MainActor static func main()throws{if CommandLine.arguments.contains("--self-test"){let colors=buckets([255,0,0,255,255,0,0,255,0,255,0,255]);precondition(colors.first!.0==0xF00&&colors.first!.1==2);print("Model checks passed");return};let app=NSApplication.shared;let delegate=Delegate();app.delegate=delegate;app.run()}}
